import pandas as pd
from sklearn.cluster import DBSCAN

def task_func(data, cols):
    df = data.copy() if isinstance(data, pd.DataFrame) else pd.DataFrame(data)

    if df.empty:
        df["Cluster"] = pd.Series(dtype="int64")
        return df

    if cols is None:
        raise ValueError("'cols' must be provided and contain at least one column name.")

    if isinstance(cols, (str, bytes)):
        cols = [cols]
    else:
        cols = list(cols)

    if not cols:
        raise ValueError("'cols' must contain at least one column name.")

    missing = [col for col in cols if col not in df.columns]
    if missing:
        raise KeyError(f"The following columns are missing from the DataFrame: {missing}")

    X = df.loc[:, cols].apply(pd.to_numeric, errors="coerce")

    if X.isna().any().any():
        raise ValueError("Selected columns must be numeric and contain no missing values.")

    df["Cluster"] = DBSCAN(eps=3, min_samples=2).fit_predict(X)
    return df
